struct Raw {int32_t winner;uint32_t best,second,count,disparity,confidence,valid;};
struct Observation {uint32_t lr_valid,depth,confidence,metric_valid,provenance,source_low,source_high,age_low,age_high;};
struct SelectParams {uint64_t lo,hi,offsets,sums,paths,raw,obs,rect_support;uint32_t width,height,disparities,eye,max_words;float numerator,principal_offset;uint32_t source_low,source_high;uint64_t status,metric_lut;};
struct SelectPush {uint64_t parameters;};struct SumResetPush {uint64_t sums;uint32_t words;};
static_assert(sizeof(Raw)==28&&sizeof(Observation)==36&&sizeof(SelectParams)==120);
constexpr uint32_t NAN_BITS=0x7fc00000u;constexpr uint32_t SRC_LO=0xabcdef01u,SRC_HI=0x12345678u;
static uint32_t confidence_rte(uint32_t best,uint32_t second){require(best<second&&second<=224,"score outside confidence contract");uint64_t n=second-best,d=second;int e=0;while((n<<unsigned(-e))<d)--e;uint64_t scaled=n<<unsigned(23-e),q=scaled/d,r=scaled%d;if(2*r>d||(2*r==d&&(q&1)))++q;if(q==0x1000000){q>>=1;++e;}return uint32_t((e+127)<<23)|uint32_t(q-0x800000);}
static std::vector<Raw> scalar_select(const Fixture& f,const Output& out){size_t n=f.lo.size();std::vector<Raw> raw(n);for(size_t i=0;i<n;++i){Raw r{-1,INF,INF,0,NAN_BITS,0,0};for(uint32_t q=f.lo[i];q<f.hi[i];++q){auto v=out.sums[f.offsets[i]+q-f.lo[i]];if(v==INF)continue;require(v<=224,"aggregate outside score contract");++r.count;if(v<r.best){r.second=r.best;r.best=v;r.winner=int32_t(q);}else if(v<r.second)r.second=v;}bool restricted=(r.winner==int32_t(f.lo[i])&&f.lo[i]>0)||(r.winner==int32_t(f.hi[i])-1&&f.hi[i]<f.d);if(r.count>=2&&r.winner>0&&r.second>r.best&&!restricted){r.valid=1;r.disparity=std::bit_cast<uint32_t>(float(r.winner));r.confidence=confidence_rte(r.best,r.second);}raw[i]=r;}return raw;}
static std::vector<Observation> scalar_obs(uint32_t w,uint32_t h,const std::vector<Raw>& raw,const std::vector<uint32_t>& support,float numerator,float cx){size_t n=size_t(w)*h;require(raw.size()==2*n&&support.size()==2*n,"reference extent");std::vector<Observation> output(2*n);for(size_t t=0;t<2*n;++t){size_t eye=t/n,i=t%n;auto a=raw[t];Observation o{0,NAN_BITS,0,0,0,INF,INF,0,0};if(a.valid){int x=int(i%w),target=eye?x+a.winner:x-a.winner;if(target>=0&&target<int(w)){auto b=raw[(1-eye)*n+(i/w)*w+size_t(target)];if(b.valid&&std::abs(a.winner-b.winner)<=1)o.lr_valid=1;}}if(o.lr_valid&&support[t]){float denominator=float(a.winner)-cx;float z=numerator/denominator;if(a.winner>0&&denominator>0&&std::isfinite(z)&&z>0){o.depth=std::bit_cast<uint32_t>(z);o.confidence=a.confidence;o.metric_valid=1;o.provenance=1;o.source_low=SRC_LO;o.source_high=SRC_HI;}}output[t]=o;}return output;}
static Fixture selection_input(bool big,uint32_t eye){if(big)return image_fixture(eye);auto f=fixture(0);for(size_t i=0;i<f.lo.size();++i){auto width=f.hi[i]-f.lo[i];f.lo[i]=0;f.hi[i]=width;for(uint32_t q=0;q<width;++q)f.cost[f.offsets[i]+q]=uint32_t(std::min(std::abs(int(q)-2)+int(eye!=0&&i%3==0&&q==3),24));}return f;}
