static std::vector<uint32_t> read_spv(const std::string& path){std::ifstream in(path,std::ios::binary|std::ios::ate);require(bool(in),"missing shader");auto bytes=size_t(in.tellg());require(bytes&&bytes%4==0&&bytes<=UINT32_MAX,"shader bytes");std::vector<uint32_t> words(bytes/4);in.seekg(0);require(bool(in.read(reinterpret_cast<char*>(words.data()),std::streamsize(bytes))),"shader read");return words;}
struct Witness {std::array<Fixture,2> f;std::array<Output,2> sums;std::vector<Raw> raw;std::vector<Observation> obs;std::vector<uint32_t> support;};
static Witness witnesses(){Witness w;const uint32_t n=12;for(uint32_t eye=0;eye<2;++eye){auto& f=w.f[eye];f.w=n;f.h=1;f.d=128;f.lo.assign(n,0);f.hi.assign(n,8);f.lo[0]=2;f.hi[7]=3;f.offsets.resize(n+1);for(uint32_t i=0;i<n;++i)f.offsets[i+1]=f.offsets[i]+16;auto& sums=w.sums[eye].sums;sums.assign(n*16,INF);for(uint32_t i=0;i<n;++i){for(uint32_t q=f.lo[i];q<f.hi[i];++q)sums[f.offsets[i]+q-f.lo[i]]=20;sums[f.offsets[i]+2-f.lo[i]]=1;if(f.hi[i]>3)sums[f.offsets[i]+3-f.lo[i]]=3;}sums[f.offsets[1]+3]=1;for(uint32_t q=0;q<8;++q){if(q!=2)sums[f.offsets[8]+q]=INF;sums[f.offsets[9]+q]=INF;}sums[f.offsets[10]]=0;if(eye==1){sums[f.offsets[0]+1]=1;sums[f.offsets[3]+2]=3;sums[f.offsets[3]+3]=1;sums[f.offsets[4]+2]=3;sums[f.offsets[4]+4]=1;}auto r=scalar_select(f,w.sums[eye]);w.raw.insert(w.raw.end(),r.begin(),r.end());}w.support.assign(2*n,1);w.support[5]=0;w.obs=scalar_obs(n,1,w.raw,w.support,63.125f,.25f);for(size_t eye=0;eye<2;++eye){auto begin=w.obs.begin()+eye*n;require(std::count_if(begin,begin+n,[](auto x){return x.metric_valid;})>0,"witness eye metric empty");}require(!w.raw[0].valid&&!w.raw[1].valid&&w.raw[1].second==w.raw[1].best&&!w.raw[7].valid&&!w.raw[8].valid&&!w.raw[9].valid&&!w.raw[10].valid,"witness tie endpoint and invalids");require(w.obs[5].lr_valid&&!w.obs[5].metric_valid,"witness support");require(w.raw[2].valid&&!w.obs[2].lr_valid,"witness LR");return w;}
static void witness_json(){auto w=witnesses();std::cout<<"{\"raw\":[";for(size_t i=0;i<w.raw.size();++i){if(i)std::cout<<",";auto r=w.raw[i];std::cout<<"["<<r.winner<<","<<r.best<<","<<r.second<<","<<r.count<<","<<r.disparity<<","<<r.confidence<<","<<r.valid<<"]";}std::cout<<"],\"obs\":[";for(size_t i=0;i<w.obs.size();++i){if(i)std::cout<<",";auto o=w.obs[i];std::cout<<"["<<o.lr_valid<<","<<o.depth<<","<<o.confidence<<","<<o.metric_valid<<","<<o.provenance<<","<<o.source_low<<","<<o.source_high<<","<<o.age_low<<","<<o.age_high<<"]";}std::cout<<"],\"lo\":[";for(size_t eye=0;eye<2;++eye)for(size_t i=0;i<12;++i){if(eye||i)std::cout<<",";std::cout<<w.f[eye].lo[i];}std::cout<<"],\"hi\":[";for(size_t eye=0;eye<2;++eye)for(size_t i=0;i<12;++i){if(eye||i)std::cout<<",";std::cout<<w.f[eye].hi[i];}std::cout<<"],\"support\":[";for(size_t i=0;i<w.support.size();++i){if(i)std::cout<<",";std::cout<<w.support[i];}std::cout<<"]}\n";}
