static void admit_parallel(const VkPhysicalDeviceLimits& limits,uint32_t groups) {
    require(limits.maxComputeWorkGroupInvocations>=128 && limits.maxComputeWorkGroupSize[0]>=128 &&
            limits.maxComputeWorkGroupSize[1]>=1 && limits.maxComputeWorkGroupSize[2]>=1 &&
            limits.maxComputeSharedMemorySize>=1536 && groups>0 && limits.maxComputeWorkGroupCount[0]>=groups &&
            limits.maxComputeWorkGroupCount[1]>=1 && limits.maxComputeWorkGroupCount[2]>=1,
            "parallel compute device limits insufficient");
}
static void admit_parallel_device(daxa::Device& d,uint32_t groups) {
    VkPhysicalDeviceProperties props{};
    vkGetPhysicalDeviceProperties(daxa_dvc_get_vk_physical_device(d.get()),&props);
    admit_parallel(props.limits,groups);
}
struct FusedParams {uint64_t lo,hi,offsets,sums,paths,own,other,own_support,other_support;uint32_t width,height,disparities,p1,p2,eye;};
static_assert(sizeof(FusedParams)==96);
struct FusedImages {std::array<std::vector<uint32_t>,2> desc,support;};
static FusedImages fused_images(uint32_t w,uint32_t h) {
    size_t n=size_t(w)*h;FusedImages images;
    for(auto& a:images.desc)a.resize(n);for(auto& a:images.support)a.resize(n,1);
    for(uint32_t y=0;y<h;++y)for(uint32_t x=0;x<w;++x) {
        size_t i=size_t(y)*w+x;
        auto pattern=[&](uint32_t u){return ((u*0x45671u+y*0x9631u)^(u*0x43e7u+y*0x45321u))&0xffffffu;};
        images.desc[0][i]=pattern(x);images.desc[1][i]=pattern(x+2);
        if(w>7&&i%97==0) images.support[0][i]=0;
        if(w>7&&i%89==0) images.support[1][i]=0;
    }return images;
}
static void fused_cpu_cost(Fixture& f,const FusedImages& images,uint32_t eye) {
    for(size_t i=0;i<f.lo.size();++i)for(uint32_t d=f.lo[i];d<f.hi[i];++d) {
        auto j=f.offsets[i]+d-f.lo[i];int x=int(i%f.w);int target=eye?x+int(d):x-int(d);f.cost[j]=INF;
        if(images.support[eye][i]&&target>=0&&target<int(f.w)) {size_t other=i/f.w*f.w+size_t(target);if(images.support[1-eye][other])f.cost[j]=uint32_t(std::popcount(images.desc[eye][i]^images.desc[1-eye][other]));}
    }
}
